rare_regions.rare_region_code:
always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            baud_counter <= '0;
            baud_tick <= 1'b0;
        end else begin
            if (baud_counter == DIVISOR - 1) begin
                baud_counter <= '0;
                baud_tick <= 1'b1;
            end else begin
                baud_counter <= baud_counter + 1;
                baud_tick <= 1'b0;
            end
        end
    end

always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

`ifdef FORMAL

        assert property (@(posedge clk) disable iff (!rst_n)
            (state == IDLE || state == STOP_BIT) |-> tx_out == 1'b1
        );

        assert property (@(posedge clk) disable iff (!rst_n)
            (state != IDLE) |-> tx_ready == 1'b0
        );
    `endif

initial begin
    rst_n = 0;
    tx_valid = 0;
    tx_data = 8'h00;

    #20 rst_n = 1;
    #50;

    @(posedge clk);
    tx_data = 8'h55;
    tx_valid = 1;
    @(posedge clk);
    tx_valid = 0;

    wait(tx_ready);
    #1000;

    @(posedge clk);
    tx_data = 8'hAA;
    tx_valid = 1;
    @(posedge clk);
    tx_valid = 0;

    wait(tx_ready);
    #1000;

    $finish;
end
